        Assert.Null(ParcelaDoRanking.DoPremio(reprovado, doReprovado, _fatos.Calendario));
    }

    [Fact]
    public void Premio_em_averiguacao_nao_pontua_e_revogado_tambem_nao()
    {
        var (premio, evento) = Aprovado(Data(10, 1));
