        var bruno = CadastroElegivel.Aluno("20260102", "bruno.lima@al.unieduk.com.br", "Bruno Lima", mundo.Cc, 3);
        mundo.Renata = Usuario.CriarPeloSeed(renata, "renataA", agora);
