    private static async Task<Ok<PaginaDeAlunosResponse>> BuscarAsync(
        string? termo,
        string? curso,
        [Range(1, int.MaxValue)] int? semestre,
        string? cursor,
        ClaimsPrincipal principal,
        BuscaDeAlunosHandler handler,
        IArmazenamentoDeFotos armazenamento,
