      <Pressable
        role="link"
        accessibilityLabel="Ver prêmios"
        hitSlop={8}
        onPress={onVerPremios}
      >
        <Text style={[textStyles.secao, styles.sublinhado, { color: link }]}>
          Ver prêmios
        </Text>
      </Pressable>
    </View>
  );
}

