    mockRoteador.canGoBack.mockReturnValueOnce(false);
    await renderComApi(<RankingsScreen inicial="geral" />, api);

    await apertar("button", "Voltar");
    expect(mockRoteador.replace).toHaveBeenCalledWith("/perfil");
  });
