test("capturas dos rankings @celular", async ({ page, request }, info) => {
  test.setTimeout(240_000);
  const tema = info.project.name.replace("celular-", "");
  const foto = (nome: string) =>
    page.screenshot({ path: path.join(SAIDA, `${nome}-${tema}.png`) });

  const professora = await novaProfessora(request);
  const ana = await novaConta(request, "Ana Souza");
  const maria = await novaConta(request, "Maria Costa");
  const joao = await novaConta(request, "João Lima");
  const pedro = await novaConta(request, "Pedro Alves");
  const bia = await novaConta(request, "Bia Rocha");
  for (const aluno of [ana, maria, joao, pedro, bia]) {
    matricular(aluno, professora.turmaId);
  }

  const daProfessora = comToken(
    await token(request, professora.email, professora.senha),
  );
  const alunos: { id: string; nomeDeExibicao: string }[] = await (
    await request.get(`/api/v1/professor/turmas/${professora.turmaId}/alunos`, {
      headers: daProfessora,
    })
  ).json();
  const id = (nome: string) =>
    alunos.find((aluno) => aluno.nomeDeExibicao === nome)!.id;
  const conceder = async (nome: string, itens: string[]) => {
    for (const item of itens) {
      const resposta = await request.post(
        `/api/v1/professor/turmas/${professora.turmaId}/medalhas`,
        { headers: daProfessora, data: { alunoId: id(nome), item } },
      );
      expect(resposta.status()).toBe(201);
    }
  };
  await conceder("Maria Costa", ["M01", "M01", "M02", "M02", "M03"]);
  await conceder("Pedro Alves", ["M01", "M02", "M03"]);
  await conceder("Ana Souza", ["M01", "M01", "M02"]);
  await conceder("João Lima", ["M01"]);

  const daAna = comToken(await token(request, ana.email, ana.senha));
  for (const nome of ["Maria Costa", "João Lima", "Pedro Alves"]) {
    expect(
      (await request.put(`/api/v1/seguindo/${id(nome)}`, { headers: daAna }))
        .status(),
    ).toBe(204);
  }

  // Pedro vira ex-aluno (a tela da instituição é do passo 12) e o ranking é recalculado.
  sql(
    `UPDATE usuario SET ex_aluno_desde = now(), sufixo = 'EX' WHERE id = '${id("Pedro Alves")}';
     INSERT INTO trabalho (tipo, carga, estado, tentativas, criado_em, disponivel_em)
     VALUES ('recalcular-ranking', '{}', 'pendente', 0, now(), now() + interval '11 seconds');`,
  );
  await page.waitForTimeout(16_000);

  await entrar(page, ana);
  await page.getByRole("tab", { name: "Perfil" }).click();
  await expect(page.getByText(/pts · #\d/)).toBeVisible({ timeout: 30_000 });
  await foto("perfil");

  await page.getByRole("link", { name: /Abrir rankings/ }).click();
  await expect(page.getByText("Ana Souza · você").first()).toBeVisible();
  await page.getByRole("radio", { name: "Quem eu sigo" }).click();
  await expect(page.getByText("Pedro Alves")).toBeVisible();
  await foto("rankings-historico-quem-eu-sigo");

  await page.getByRole("radio", { name: "Todos" }).click();
  await page.getByRole("radio", { name: "Geral" }).click();
  await expect(page.getByText(/Semestre \d\/\d{4}/)).toBeVisible();
  await page.waitForTimeout(800);
  await foto("rankings-geral");

  await page.getByRole("radio", { name: "Curso" }).click();
  await page.getByRole("radio", { name: "Quem eu sigo" }).click();
  await expect(page.getByText("Maria Costa")).toBeVisible();
  await foto("rankings-curso-quem-eu-sigo");

  await page.goto("/busca");
  await expect(
    page.getByRole("button", { name: "Ranking do curso" }),
  ).toBeVisible();
  await foto("busca");

  await page.goto("/perfil");
  await page.getByRole("button", { name: "Menu" }).click();
  await page.getByRole("button", { name: "Sair" }).click();
  await entrar(page, bia);
  await page.goto("/rankings?visao=geral");
  await expect(page.getByText("Sem posição ainda")).toBeVisible();
  await foto("rankings-sem-posicao");
});

