internal sealed class ConsultaDePosts(MaxxDbContext db) : IConsultaDePosts
{
    public async Task<PostLido?> PostAsync(Guid id, Guid leitorId, CancellationToken cancellationToken) =>
        (await PostsAsync([id], leitorId, cancellationToken)).GetValueOrDefault(id);

    // Poucas consultas para a página inteira, não por post: os posts com autor e contagens,
    // depois os prêmios que eles citam, um tipo por consulta.
    public async Task<IReadOnlyDictionary<Guid, PostLido>> PostsAsync(
        IReadOnlyCollection<Guid> ids, Guid leitorId, CancellationToken cancellationToken)
    {
        var linhas = await (
                from post in db.Set<Post>()
                join autor in db.Set<Usuario>() on post.AutorId equals autor.Id
                join cadastro in db.Set<CadastroElegivel>() on autor.CadastroElegivelId equals cadastro.Id
                join curso in db.Set<Curso>() on cadastro.CursoId equals curso.Id into cursos
                from curso in cursos.DefaultIfEmpty()
                where ids.Contains(post.Id) && post.RemovidoEm == null
                select new
                {
                    post.Id,
                    post.Legenda,
                    post.ChaveDaFotoDoFeed,
                    post.ChaveDaFotoDaGrade,
                    post.MedalhaId,
                    post.PremioParticipacaoId,
                    post.ConquistaId,
                    post.CriadoEm,
                    AutorId = autor.Id,
                    autor.NomeDeExibicao,
                    autor.Prefixo,
                    autor.Sufixo,
                    FotoDoAutor = autor.ChaveDaFotoDaGrade,
                    Curso = curso == null ? null : curso.Sigla,
                    cadastro.Semestre,
                    Curtidas = db.Set<Curtida>().Count(curtida => curtida.PostId == post.Id),
                    Comentarios = db.Set<Comentario>().Count(comentario => comentario.PostId == post.Id && comentario.RemovidoEm == null),
                    Curtiu = db.Set<Curtida>().Any(curtida => curtida.PostId == post.Id && curtida.UsuarioId == leitorId),
                })
            .AsNoTracking()
            .ToListAsync(cancellationToken);

        var medalhas = await MedalhasAsync([.. linhas.Where(linha => linha.MedalhaId is not null).Select(linha => linha.MedalhaId!.Value)], cancellationToken);

        // Em averiguação, o prêmio é visível só ao aluno e à instituição (produto.md 4.7 e 9.1):
        // para os outros, o post continua no ar, sem o prêmio, sem pontos nem tier.
        var leitorEInstituicao = await db.Set<Usuario>()
            .Where(usuario => usuario.Id == leitorId)
            .Select(usuario => (usuario.Papeis & Papeis.Instituicao) != 0)
            .SingleOrDefaultAsync(cancellationToken);
        var conquistas = await ConquistasAsync(
            [.. linhas.Where(linha => linha.ConquistaId is not null).Select(linha => linha.ConquistaId!.Value)], cancellationToken);
        var participacoes = await PremiosParticipacaoAsync(
            [.. linhas.Where(linha => linha.PremioParticipacaoId is not null).Select(linha => linha.PremioParticipacaoId!.Value)], cancellationToken);

        return linhas.ToDictionary(
            linha => linha.Id,
            linha => new PostLido(
                linha.Id,
                new AutorDoPost(linha.AutorId, linha.NomeDeExibicao, new Arroba(linha.Prefixo, linha.Sufixo).ToString(), linha.Curso, linha.Semestre, linha.FotoDoAutor),
                linha.Legenda,
                linha.ChaveDaFotoDoFeed,
                linha.ChaveDaFotoDaGrade,
                linha.MedalhaId is { } medalhaId
                    ? medalhas.GetValueOrDefault(medalhaId)
                    : linha.ConquistaId is { } conquistaId
                    ? conquistas.GetValueOrDefault(conquistaId)
                    : linha.PremioParticipacaoId is { } premioId
                        && participacoes.GetValueOrDefault(premioId) is { } participacao
                        && (participacao.Estado != EstadoDoPremioParticipacao.EmAveriguacao || linha.AutorId == leitorId || leitorEInstituicao)
                        ? participacao
    int Curtidas,
    int Comentarios,
    bool Curtiu)
{
    public static PostResponse De(PostLido post, IArmazenamentoDeFotos armazenamento) => new(
        post.Id,
        new AutorDoPostResponse(
            post.Autor.Id,
            post.Autor.NomeDeExibicao,
            post.Autor.Arroba,
            post.Autor.Curso,
            post.Autor.Semestre,
            Leitura(armazenamento, post.Autor.ChaveDaFoto)),
        post.Legenda,
        post is { ChaveDaFotoDoFeed: { } feed, ChaveDaFotoDaGrade: { } grade }
            ? new FotoDoPostResponse(armazenamento.UrlDeLeitura(feed).AbsoluteUri, armazenamento.UrlDeLeitura(grade).AbsoluteUri)
            : null,
        post.Premio is { } premio
    IReadOnlyList<string> Materias)
{
    public static ComprovacaoNaFilaResponse De(ComprovacaoNaFila comprovacao, IArmazenamentoDeFotos armazenamento) => new(
        comprovacao.Id,
        comprovacao.PremioId,
        comprovacao.PostId,
        new AutorDoPostResponse(
            comprovacao.Aluno.Id,
            comprovacao.Aluno.NomeDeExibicao,
            comprovacao.Aluno.Arroba,
            comprovacao.Aluno.Curso,
            comprovacao.Aluno.Semestre,
            PostResponse.Leitura(armazenamento, comprovacao.Aluno.ChaveDaFoto)),
        comprovacao.Item,
        comprovacao.NomeDoItem,
    bool Curtiu);

// Curso e semestre do aluno são perfil (produto.md 3); o RA nunca sai daqui.
// A foto é a derivada da grade (~320²), que basta para o avatar.
public sealed record AutorDoPost(Guid Id, string NomeDeExibicao, string Arroba, string? Curso, int? Semestre, string? ChaveDaFoto);

