import path from "node:path";

import { expect, test } from "@playwright/test";

import { novaConta } from "./apoio/contas";
import { matricular, novaProfessora } from "./apoio/medalhas";
import { comToken, token } from "./apoio/premios";

const SAIDA = process.env.MAXX_CAPTURAS!;

test("capturas do feed e de troféus @celular", async ({ page, request }, info) => {
  test.setTimeout(180_000);
  const tema = info.project.name.replace("celular-", "");
  const foto = (nome: string) =>
    page.screenshot({ path: path.join(SAIDA, `${nome}-${tema}.png`) });

  const professora = await novaProfessora(request);
  const ana = await novaConta(request, "Ana Souza");
  matricular(ana, professora.turmaId);
  const daProfessora = comToken(
    await token(request, professora.email, professora.senha),
  );
  const alunos: { id: string; arroba: string }[] = await (
    await request.get(`/api/v1/professor/turmas/${professora.turmaId}/alunos`, {
      headers: daProfessora,
    })
  ).json();
  const anaId = alunos.find((aluno) => aluno.arroba === `@${ana.prefixo}-CC`)!.id;
  for (const item of ["M01", "M01", "M02"]) {
    const resposta = await request.post(
      `/api/v1/professor/turmas/${professora.turmaId}/medalhas`,
      { headers: daProfessora, data: { alunoId: anaId, item } },
    );
    expect(resposta.status()).toBe(201);
  }
  const daAna = comToken(await token(request, ana.email, ana.senha));
  expect(
    (
      await request.post("/api/v1/posts", {
        headers: daAna,
        data: { legenda: "Três medalhas no bimestre. Bora pra próxima!" },
      })
    ).status(),
  ).toBe(201);
  await page.waitForTimeout(12_000);

  await page.goto("/login");
  await page.getByLabel("RA ou e-mail").fill(ana.email);
  await page.getByLabel("Senha", { exact: true }).fill(ana.senha);
  await page.getByRole("button", { name: "Entrar", exact: true }).click();
  await expect(page.getByText(/1º semestre · #\d/).first()).toBeVisible({
    timeout: 30_000,
  });
  await foto("feed");

  await page.getByRole("tab", { name: "Troféus" }).click();
  await expect(page.getByText(/pts · #\d/)).toBeVisible();
  await page.waitForTimeout(800);
  await foto("trofeus");
});

